// Packaged-consumer lifecycle driver. Appended to probe.js by the prepare
// script; function declarations hoist, so packagedRun() below can be invoked
// by the patched probe entry point.
const packagedStageKey = "packaged-stage";

// Each runner invocation writes a fresh public/packaged-run.json. A new id
// resets the stored stage without touching application data, so repeated runs
// always start at "acceptance" while stages still survive app relaunches and
// asset-update installs within one run.
async function packagedStage() {
  try {
    const run = await (
      await fetch("/packaged-run.json", { cache: "no-store" })
    ).json();
    if (localStorage.getItem("packaged-run") !== run.id) {
      localStorage.setItem("packaged-run", run.id);
      localStorage.removeItem(packagedStageKey);
    }
  } catch {}
  return localStorage.getItem(packagedStageKey) || "acceptance";
}

function packagedLog(stage, extra = {}) {
  console.log(
    "PACKAGED_LIFECYCLE",
    JSON.stringify({ stage, passed: true, ...extra }),
  );
}

function packagedFail(stage, error) {
  console.log(
    "PACKAGED_LIFECYCLE",
    JSON.stringify({ stage, passed: false, error: String(error) }),
  );
}

async function packagedWait(predicate, timeout = 15000) {
  const deadline = Date.now() + timeout;
  while (!predicate()) {
    if (Date.now() > deadline) throw new Error("lifecycle check timed out");
    await new Promise((resolve) => setTimeout(resolve, 50));
  }
}

// Public dispose (iOS, requested from the document and performed by the host
// page) is deliberately different from the Android native plugin stop below.
function packagedRequestStop() {
  if (window.Capacitor?.getPlatform() === "ios")
    localStorage.setItem("packaged-stop", "requested");
  else
    return window.Capacitor.nativePromise("WorkersCapacitor", "stop", {}).then(
      () => console.log("PACKAGED_STOP", "android native stop completed"),
    );
}

// Fresh rendering and local API access on the render entry page. version is
// " v2" after the bundled Worker/static asset update.
async function packagedRendered(version) {
  const framework = document.title.startsWith("Hono") ? "Hono" : "Express";
  await packagedWait(
    () =>
      document.title === framework + " document" + version &&
      document.querySelector("#module")?.textContent ===
        "module ready" + version &&
      document.querySelector("#api")?.textContent === framework + " API ready",
  );
  if (window.documentSentinel)
    throw new Error("document window was not recreated");
  const api = await (await fetch("/api/message")).json();
  if (api.message !== framework + " API ready")
    throw new Error("local API unavailable");
}

// Android-only: the Fetch-only migration contract previously exercised through
// the CDP --lifecycle probe, reused here against the packaged document Service
// Worker. public/lifecycle.js is an esbuild IIFE of the installed package
// entry generated by the prepare script.
async function packagedMigration() {
  await new Promise((resolve, reject) => {
    const script = document.createElement("script");
    script.src = "/lifecycle.js";
    script.onload = resolve;
    script.onerror = () => reject(new Error("lifecycle bundle missing"));
    document.head.appendChild(script);
  });
  const isDocumentWorker = (worker) =>
    worker && new URL(worker.scriptURL).pathname === "/workers-capacitor-sw.js";
  const before = await navigator.serviceWorker.getRegistrations();
  const hadDocumentRegistration = before.some((registration) =>
    [registration.active, registration.waiting, registration.installing].some(
      isDocumentWorker,
    ),
  );
  const app = DocumentLifecycleTest.workersCapacitor({
    baseURL: "https://worker.invalid/api",
    worker: { fetch: () => new Response("fetch-only") },
  });
  let result;
  try {
    await app.ready;
    const response = await fetch("/unlisted-lifecycle-check.html");
    const text = await response.text();
    const registrations = await navigator.serviceWorker.getRegistrations();
    result = {
      hadDocumentRegistration,
      controlled: !!navigator.serviceWorker.controller,
      documentRegistrations: registrations.filter((registration) =>
        [
          registration.active,
          registration.waiting,
          registration.installing,
        ].some(isDocumentWorker),
      ).length,
      nativeAssetFallback: response.status === 404 && text === "",
      api: await (await fetch("/api/check")).text(),
    };
  } finally {
    await app.dispose();
    await window.Capacitor.nativePromise("WorkersCapacitor", "stop", {});
  }
  if (
    !result.hadDocumentRegistration ||
    !result.controlled ||
    result.documentRegistrations !== 0 ||
    !result.nativeAssetFallback ||
    result.api !== "fetch-only"
  )
    throw new Error("migration: " + JSON.stringify(result));
  return result;
}

// Runs after the 50 acceptance cases report. The runner backgrounds then
// foregrounds the app after the result line; verify rendering and the local
// API still work before stopping this stage. Evidence of a real OS transition
// comes from the platform signals only: iOS delivers the Capacitor scene
// lifecycle as document "pause"/"resume" events, and Android WebView reports
// visibilitychange.
async function packagedAfterReport(passed) {
  if (!passed) return;
  // Advance early: WebView storage commits asynchronously and the runner stops
  // the app process soon after this stage's stop request.
  localStorage.setItem(packagedStageKey, "relaunch");
  try {
    // iOS pause/resume evals can be delivered after the process resumes, so
    // accept either order; both exist only on a real scene transition.
    let paused = document.hidden;
    let resumed = false;
    document.addEventListener("visibilitychange", () => {
      if (document.hidden) paused = true;
      else if (paused) resumed = true;
    });
    document.addEventListener("pause", () => (paused = true));
    document.addEventListener("resume", () => (resumed = true));
    await packagedWait(() => paused, 30000);
    await packagedWait(() => resumed, 30000);
    if (!document.querySelector("#native-document-report"))
      throw new Error("rendered report missing after foregrounding");
    // The acceptance sequence ends on /pages/forms; the framework name comes
    // from the stored report, not the current document title.
    const framework = JSON.parse(
      localStorage.getItem("native-document-result") || "{}",
    ).framework;
    const api = await (await fetch("/api/message")).json();
    if (api.message !== framework + " API ready")
      throw new Error("local API unavailable after foregrounding");
    packagedLog("background");
  } catch (error) {
    packagedFail("background", error);
  }
  await packagedRequestStop();
}

async function packagedRun() {
  if (!location.pathname.startsWith("/pages/")) return;
  const stage = await packagedStage();
  if (stage === "acceptance") return runDocumentProbe();
  if (stage === "done") return;
  // Lifecycle stages only ever load the render entry page.
  if (location.pathname !== "/pages/home") return;
  const next = { relaunch: "update", update: "reinit", reinit: "done" }[stage];
  if (!next) {
    packagedFail(stage, new Error("unknown stage " + stage));
    return;
  }
  // Advance early: WebView storage commits asynchronously and the runner stops
  // the app process soon after this stage's stop request.
  localStorage.setItem(packagedStageKey, next);
  let passed = true;
  try {
    await packagedRendered(stage === "relaunch" ? "" : " v2");
    const extra = {};
    if (stage === "update") {
      const updated = await (await fetch("/rendering/update-v2.txt")).text();
      if (updated.trim() !== "v2")
        throw new Error("updated bundled asset not served");
    }
    if (stage === "reinit" && window.Capacitor?.getPlatform() === "android")
      extra.migration = await packagedMigration();
    packagedLog(stage, extra);
  } catch (error) {
    passed = false;
    packagedFail(stage, error);
  }
  if (next === "done")
    console.log(
      "PACKAGED_LIFECYCLE",
      JSON.stringify({ stage: "complete", passed }),
    );
  await packagedRequestStop();
  // Android keeps this document alive after native stop. Reloading while no
  // host exists lets the persistent Service Worker restart the bundled
  // bootstrap, which reinitializes native document rendering.
  if (stage === "update" && window.Capacitor?.getPlatform() === "android")
    location.reload();
}
